"""CEGAR-style counterexample analysis, minimization, and predicate refinement.

Implements a Counterexample-Guided Abstraction Refinement loop on top of
Z3's Python API:

  1. Counterexample trace data structures (State / Transition / Counterexample)
  2. CEXValidator      - concrete validation of traces (real vs. spurious)
  3. PredicateRefiner  - Craig-style interpolation (via quantifier
                         elimination), predicate strengthening, and SMT-based
                         trace minimization
  4. AbstractDomain    - predicate-abstraction state management
  5. CEGARLoop         - the main refinement loop; each iteration verifies a
                         Boolean predicate abstraction encoded as Horn clauses
                         and solved with the Spacer fixedpoint engine

Transition systems follow the convention used by spacer_verifier: formulas
over state variables, with the next-state copy of variable ``x`` named ``x'``.
"""

from itertools import product

from z3 import (And, Or, Not, BoolVal, IntVal, Solver, Goal, Tactic, Exists,
                Fixedpoint, Function, BoolSort, Const, substitute, simplify,
                sat, unsat, is_true, is_false, is_const, is_bool, is_and,
                is_or, is_not, is_eq, is_le, is_lt, is_ge, is_gt,
                is_distinct, is_int_value, Z3_OP_UNINTERPRETED)

from spacer_verifier import verify_transition_system

# ---------------------------------------------------------------------------
# Shared helpers
# ---------------------------------------------------------------------------


def _consts_of(expr):
    """All uninterpreted constants occurring in expr, keyed by name."""
    result = {}

    def walk(e, seen):
        if e in seen:
            return
        seen.add(e)
        if is_const(e) and e.num_args() == 0 and \
                e.decl().kind() == Z3_OP_UNINTERPRETED and \
                e.decl().name() not in result:
            result[e.decl().name()] = e
        for ch in e.children():
            walk(ch, seen)

    walk(expr, set())
    return result


def _value_literal(value):
    """Z3 literal for a concrete Python value."""
    if isinstance(value, bool):
        return BoolVal(value)
    return IntVal(value)


def _to_python(z3val):
    """Python int/bool for a Z3 model value."""
    if is_int_value(z3val):
        return z3val.as_long()
    if is_true(z3val):
        return True
    if is_false(z3val):
        return False
    return z3val  # fallback: keep the Z3 term


def _holds(expr, values):
    """True iff expr evaluates to True under concrete variable values."""
    consts = _consts_of(expr)
    pairs = [(c, _value_literal(values[c.decl().name()]))
             for c in consts.values() if c.decl().name() in values]
    return is_true(simplify(substitute(expr, pairs)))


def _holds_trans(trans_rel, src_values, dst_values):
    """True iff trans_rel holds between two concrete states.

    Unprimed variables are read from src_values, primed ones (name + "'")
    from dst_values using the unprimed base name.
    """
    pairs = []
    for c in _consts_of(trans_rel).values():
        name = c.decl().name()
        if name.endswith("'"):
            base = name[:-1]
            if base in dst_values:
                pairs.append((c, _value_literal(dst_values[base])))
        elif name in src_values:
            pairs.append((c, _value_literal(src_values[name])))
    return is_true(simplify(substitute(trans_rel, pairs)))


def _atoms(expr):
    """Atomic predicates of a Boolean formula (connectives stripped).

    Atoms are deduplicated by their s-expression and trivial constants
    (True/False) are dropped.
    """
    atoms = {}

    def rec(e):
        if is_true(e) or is_false(e):
            return
        if is_and(e) or is_or(e):
            for ch in e.children():
                rec(ch)
        elif is_not(e):
            rec(e.arg(0))
        elif is_bool(e) and e.decl().name() in ("=>", "xor", "ite"):
            for ch in e.children():
                rec(ch)
        elif is_eq(e) and is_bool(e.arg(0)):
            atoms.setdefault(e.sexpr(), e)  # iff: treat as atomic
        else:
            atoms.setdefault(e.sexpr(), e)

    rec(simplify(expr))
    return list(atoms.values())


# ---------------------------------------------------------------------------
# 1. Counterexample data structures
# ---------------------------------------------------------------------------


class State:
    """One concrete state: maps variable names to concrete values.

    An optional ``constraint`` (a Z3 formula over the canonical state
    variables) may accompany the state; it is used instead of the concrete
    values when building interpolation queries for abstract (spurious)
    traces.
    """

    def __init__(self, values, constraint=None):
        self.values = dict(values)
        self.constraint = constraint

    def __repr__(self):
        return f"State({self.values})"


class Transition:
    """A single step from src to dst, labelled with an action name."""

    def __init__(self, src, dst, action):
        self.src = src
        self.dst = dst
        self.action = action

    def __repr__(self):
        return f"Transition({self.action}: {self.src} -> {self.dst})"


class Counterexample:
    """A full counterexample trace: a list of transitions."""

    def __init__(self, transitions):
        self.transitions = list(transitions)

    @property
    def length(self):
        """Number of transitions in the trace."""
        return len(self.transitions)

    @property
    def states(self):
        """All states visited by the trace, in order."""
        if not self.transitions:
            return []
        return [t.src for t in self.transitions] + \
            [self.transitions[-1].dst]

    def get_variable_trace(self, var_name):
        """Values of one variable across all states of the trace."""
        return [s.values.get(var_name) for s in self.states]

    def __repr__(self):
        return f"Counterexample(length={self.length})"


class ValidationResult:
    """Outcome of concrete counterexample validation.

    ``first_spurious_step`` is None for a real counterexample.  Otherwise it
    identifies the first failing check: 0 = the initial state does not
    satisfy init_cond; i (1-based) = transition i-1 is not consistent with
    trans_rel; length+1 = the final state does not violate the safety
    property.
    """

    def __init__(self, is_real, first_spurious_step):
        self.is_real = is_real
        self.first_spurious_step = first_spurious_step

    def __repr__(self):
        return (f"ValidationResult(is_real={self.is_real}, "
                f"first_spurious_step={self.first_spurious_step})")


class CEGARResult:
    """Outcome of a CEGAR run.

    ``cex`` is the minimized counterexample (unsafe runs only);
    ``original_cex`` keeps the raw, unminimized witness for comparison.
    """

    def __init__(self, safe, iterations, predicates, cex=None):
        self.safe = safe
        self.iterations = iterations
        self.predicates = list(predicates)
        self.cex = cex
        self.original_cex = None

    def __repr__(self):
        return (f"CEGARResult(safe={self.safe}, "
                f"iterations={self.iterations}, "
                f"predicates={len(self.predicates)}, "
                f"cex={self.cex.length if self.cex else None})")


# ---------------------------------------------------------------------------
# 2. Concrete counterexample validation
# ---------------------------------------------------------------------------


class CEXValidator:
    """Validates whether a counterexample trace is real or spurious by
    concrete step-by-step simulation against the transition system."""

    def validate(self, cex, init_cond, trans_rel, safety):
        """Simulate the trace concretely.

        Returns ValidationResult(is_real, first_spurious_step).  The trace is
        real iff the initial state satisfies init_cond, every step satisfies
        trans_rel with the concrete values, and the final state violates
        safety.
        """
        states = cex.states
        if not states:
            return ValidationResult(False, 0)
        if not _holds(init_cond, states[0].values):
            return ValidationResult(False, 0)
        for i, t in enumerate(cex.transitions):
            if not _holds_trans(trans_rel, t.src.values, t.dst.values):
                return ValidationResult(False, i + 1)
        if _holds(safety, states[-1].values):
            return ValidationResult(False, cex.length + 1)
        return ValidationResult(True, None)


# ---------------------------------------------------------------------------
# 3. Predicate refinement and trace minimization
# ---------------------------------------------------------------------------


class PredicateRefiner:
    """Computes interpolants from infeasible traces, strengthens predicate
    sets, and minimizes counterexample traces via SMT jump checks."""

    def __init__(self, state_vars, primed_vars=None):
        self.state_vars = list(state_vars)
        if primed_vars is None:
            primed_vars = [Const(v.decl().name() + "'", v.sort())
                           for v in self.state_vars]
        self.primed_vars = list(primed_vars)
        self._qe = Tactic("qe")

    # -- interpolation -----------------------------------------------------

    def _state_constraint(self, cex, i, copies):
        """Constraint characterizing position i of the trace."""
        st = cex.states[i]
        if st.constraint is not None:
            return substitute(st.constraint, zip(self.state_vars, copies[i]))
        return And([c == _value_literal(st.values[c.decl().name()])
                    for c in copies[i] if c.decl().name() in st.values])

    def extract_interpolants(self, cex, trans_rel):
        """Craig-style interpolants between consecutive steps of the trace.

        For each cut i the path formula is split into a prefix A_i (states
        0..i) and a suffix B_i (states i..n) sharing only the position-i
        variables; A_i /\ B_i is the (infeasible) trace formula.  The
        interpolant is the exact projection of A_i onto the shared
        variables, computed with Z3's quantifier elimination - a strongest
        postcondition interpolant.  Returns a list of formulas over the
        canonical state variables.
        """
        n = cex.length
        if n == 0:
            return []
        copies = [[Const(f"{v.decl().name()}#{i}", v.sort())
                   for v in self.state_vars] for i in range(n + 1)]
        steps = [substitute(trans_rel,
                            list(zip(self.state_vars + self.primed_vars,
                                     copies[i] + copies[i + 1])))
                 for i in range(n)]
        sc = [self._state_constraint(cex, i, copies) for i in range(n + 1)]

        interpolants = []
        for cut in range(n + 1):
            a = And([sc[j] for j in range(cut + 1)] + steps[:cut])
            b = And([sc[j] for j in range(cut, n + 1)] + steps[cut:])
            if Solver()(a, b).__class__ is not None:
                s = Solver()
                s.add(a, b)
                if s.check() != unsat:
                    continue  # sat split: no interpolant at this cut
            others = [c for i, copy in enumerate(copies) if i != cut
                      for c in copy]
            if others:
                goal = Goal()
                goal.add(Exists(others, a))
                result = self._qe(goal)
                projected = And([f for g in result for f in g])
            else:
                projected = a
            back = substitute(projected, list(zip(copies[cut],
                                                  self.state_vars)))
            interpolants.append(simplify(back))
        return interpolants

    def strengthen_invariant(self, current_preds, new_interpolants):
        """Merge interpolant atoms into the predicate set.

        Subsumed predicates are dropped (see AbstractDomain.add_predicate).
        Returns the refined list of predicates.
        """
        domain = AbstractDomain(current_preds)
        for interpolant in new_interpolants:
            for atom in _atoms(interpolant):
                domain.add_predicate(atom)
        return list(domain.predicates)

    # -- minimization ------------------------------------------------------

    def _jump_consistent(self, trans_rel, src, dst):
        """True iff a single transition can jump from src to dst."""
        return _holds_trans(trans_rel, src.values, dst.values)

    def minimize_cex(self, cex, trans_rel):
        """Shorten the trace by skipping intermediate transitions.

        Greedy sweep: from the current state, jump directly to the furthest
        state still consistent with a single step of trans_rel.  Stutters
        and detours collapse; the first and last states are preserved.
        """
        states = cex.states
        n = len(states)
        if n <= 2:
            return cex
        keep = [0]
        i = 0
        while i < n - 1:
            j = n - 1
            while j > i + 1 and not self._jump_consistent(trans_rel,
                                                          states[i],
                                                          states[j]):
                j -= 1
            keep.append(j)
            i = j
        actions = [t.action for t in cex.transitions]
        transitions = []
        for a, b in zip(keep, keep[1:]):
            if b == a + 1:
                action = actions[a]
            else:
                action = "jump(" + ",".join(actions[a:b]) + ")"
            transitions.append(Transition(states[a], states[b], action))
        return Counterexample(transitions)


# ---------------------------------------------------------------------------
# 4. Predicate abstraction domain
# ---------------------------------------------------------------------------


class AbstractDomain:
    """Manages the current set of abstraction predicates."""

    def __init__(self, predicates=None):
        self.predicates = []
        for p in predicates or []:
            self.add_predicate(p)

    @property
    def predicate_count(self):
        return len(self.predicates)

    def abstract_state(self, concrete_state):
        """Boolean vector of predicate values on a concrete state."""
        values = concrete_state.values if isinstance(concrete_state, State) \
            else concrete_state
        return tuple(_holds(p, values) for p in self.predicates)

    def is_subsumed(self, pred_new, pred_existing):
        """True iff pred_existing implies pred_new (new adds no information,
        i.e. it is subsumed by the existing predicate)."""
        s = Solver()
        s.add(pred_existing, Not(pred_new))
        return s.check() == unsat

    def add_predicate(self, pred):
        """Add pred unless subsumed; drop existing predicates it subsumes.

        Returns True if the predicate was added.
        """
        if any(self.is_subsumed(pred, e) for e in self.predicates):
            return False
        self.predicates = [e for e in self.predicates
                           if not self.is_subsumed(e, pred)]
        self.predicates.append(pred)
        return True


# ---------------------------------------------------------------------------
# 5. CEGAR loop
# ---------------------------------------------------------------------------


class CEGARLoop:
    """Counterexample-guided abstraction refinement over predicate
    abstraction, with Spacer as the abstract-model-checking backend."""

    _fallback_counter = 0

    def __init__(self, init_cond, trans_rel, safety, max_iterations=20,
                 predicate_budget=50):
        self.init_cond = init_cond
        self.trans_rel = trans_rel
        self.safety = safety
        self.max_iterations = max_iterations
        self.predicate_budget = predicate_budget

        consts = {}
        for e in (init_cond, trans_rel, safety):
            consts.update(_consts_of(e))
        self.state_vars = sorted(
            (v for n, v in consts.items() if not n.endswith("'")),
            key=lambda v: v.decl().name())
        self.primed_vars = []
        for v in self.state_vars:
            primed = consts.get(v.decl().name() + "'")
            if primed is None:
                raise ValueError(
                    f"missing next-state variable {v.decl().name()}'")
            self.primed_vars.append(primed)

        self.validator = CEXValidator()
        self.refiner = PredicateRefiner(self.state_vars, self.primed_vars)
        self.domain = AbstractDomain(_atoms(safety))

    # -- abstract verification (Boolean abstraction as Horn clauses) -------

    def _cube_formula(self, cube, vars_):
        return And([substitute(p, list(zip(self.state_vars, vars_)))
                    if bit else
                    Not(substitute(p, list(zip(self.state_vars, vars_))))
                    for p, bit in zip(self.domain.predicates, cube)])

    def _init_cubes(self):
        """All initial abstract states (cubes covering init_cond)."""
        cubes = []
        s = Solver()
        s.add(self.init_cond)
        while s.check() == sat:
            m = s.model()
            cube = tuple(is_true(m.eval(p, model_completion=True))
                         for p in self.domain.predicates)
            cubes.append(cube)
            s.add(Not(self._cube_formula(cube, self.state_vars)))
        return cubes

    def _abstract_successors(self, cube, solver):
        """Strongest Cartesian post-image of a cube, as full cubes."""
        base = self._cube_formula(cube, self.state_vars)
        if solver.check(base, self.trans_rel) != sat:
            return []  # deadlock: no outgoing abstract transitions
        options = []
        for p in self.domain.predicates:
            pp = substitute(p, list(zip(self.state_vars, self.primed_vars)))
            pos = solver.check(base, self.trans_rel, pp) == sat
            neg = solver.check(base, self.trans_rel, Not(pp)) == sat
            options.append([b for b, ok in ((True, pos), (False, neg))
                            if ok])
        return [tuple(combo) for combo in product(*options)]

    def _verify_abstraction(self):
        """Verify the current predicate abstraction with Spacer.

        Builds the Boolean abstract transition system, encodes its
        reachability as Horn clauses, and queries the error relation with
        the Spacer engine.  Returns (safe, abstract_trace) where the trace
        is a list of cubes from an initial to a violating abstract state.
        """
        preds = self.domain.predicates
        if not preds:
            return self._concrete_verdict(), None

        init_cubes = self._init_cubes()
        solver = Solver()
        edges = []
        parent = {}
        visited = set(init_cubes)
        queue = list(init_cubes)
        violation = None
        while queue and violation is None and len(visited) <= 4096:
            cube = queue.pop(0)
            if solver.check(self._cube_formula(cube, self.state_vars),
                            Not(self.safety)) == sat:
                violation = cube
                break
            for succ in self._abstract_successors(cube, solver):
                edges.append((cube, succ))
                if succ not in visited:
                    visited.add(succ)
                    parent[succ] = cube
                    queue.append(succ)

        # Encode the abstract reachability problem as Horn clauses.
        fp = Fixedpoint()
        fp.set(engine="spacer")
        k = len(preds)
        rel = Function("AbsInv", *([BoolSort()] * k), BoolSort())
        err = Function("AbsErr", BoolSort())
        fp.register_relation(rel, err)

        def bits(cube):
            return [BoolVal(b) for b in cube]

        for c in init_cubes:
            fp.rule(rel(*bits(c)))
        for c, c2 in edges:
            fp.rule(rel(*bits(c2)), [rel(*bits(c))])
        bad = violation if violation is not None else None
        if bad is not None:
            fp.rule(err(), [rel(*bits(bad))])
        else:
            # No reachable violation cube was found during exploration;
            # still let Spacer decide on the explored graph.
            for c in visited:
                if solver.check(self._cube_formula(c, self.state_vars),
                                Not(self.safety)) == sat:
                    fp.rule(err(), [rel(*bits(c))])
        safe = fp.query(err) == unsat
        if safe or bad is None:
            return safe, None
        trace = [bad]
        while trace[-1] in parent:
            trace.append(parent[trace[-1]])
        trace.reverse()
        return False, trace

    # -- concretization / witnesses ----------------------------------------

    def _copies(self, i):
        return [Const(f"{v.decl().name()}#{i}", v.sort())
                for v in self.state_vars]

    def _states_from_model(self, m, n):
        states = []
        for i in range(n + 1):
            values = {v.decl().name(): _to_python(m.eval(c, True))
                      for v, c in zip(self.state_vars, self._copies(i))}
            states.append(State(values))
        return states

    def _concretize(self, trace):
        """Find a concrete trace following the abstract one, or None."""
        n = len(trace) - 1
        copies = [self._copies(i) for i in range(n + 1)]
        s = Solver()
        s.add(substitute(self.init_cond, list(zip(self.state_vars,
                                                  copies[0]))))
        s.add(self._cube_formula(trace[0], copies[0]))
        for i in range(n):
            s.add(substitute(self.trans_rel,
                             list(zip(self.state_vars + self.primed_vars,
                                      copies[i] + copies[i + 1]))))
            s.add(self._cube_formula(trace[i + 1], copies[i + 1]))
        s.add(Not(substitute(self.safety, list(zip(self.state_vars,
                                                   copies[n])))))
        if s.check() != sat:
            return None
        states = self._states_from_model(s.model(), n)
        return Counterexample([Transition(states[i], states[i + 1],
                                          f"step_{i}")
                               for i in range(n)])

    def _symbolic_cex(self, trace):
        """Counterexample object for an infeasible abstract trace.

        States carry their cube constraint (used by the interpolator); the
        concrete values are per-cube witnesses for validation/display.
        """
        n = len(trace) - 1
        states = []
        for i, cube in enumerate(trace):
            cf = self._cube_formula(cube, self.state_vars)
            if i == 0:
                cf = And(self.init_cond, cf)
            if i == n:
                cf = And(cf, Not(self.safety))
            s = Solver()
            s.add(cf)
            s.check()
            m = s.model()
            values = {v.decl().name(): _to_python(m.eval(v, True))
                      for v in self.state_vars}
            states.append(State(values, constraint=cf))
        return Counterexample([Transition(states[i], states[i + 1],
                                          f"abstract_step_{i}")
                               for i in range(n)])

    def _raw_witness(self, cex):
        """Raw engine witness: BMC at the minimal depth plus a slack of two.

        Mirrors the non-minimal traces produced by engines such as Spacer;
        falls back to the given trace if the deeper unrolling is infeasible.
        """
        depth = cex.length + 2
        copies = [self._copies(i) for i in range(depth + 1)]
        s = Solver()
        s.add(substitute(self.init_cond, list(zip(self.state_vars,
                                                  copies[0]))))
        for i in range(depth):
            s.add(substitute(self.trans_rel,
                             list(zip(self.state_vars + self.primed_vars,
                                      copies[i] + copies[i + 1]))))
        s.add(Not(substitute(self.safety, list(zip(self.state_vars,
                                                   copies[depth])))))
        if s.check() != sat:
            return cex
        states = self._states_from_model(s.model(), depth)
        return Counterexample([Transition(states[i], states[i + 1],
                                          f"raw_step_{i}")
                               for i in range(depth)])

    # -- fallback -----------------------------------------------------------

    def _concrete_verdict(self):
        """Verify the concrete system directly with Spacer (fallback used
        when the refinement budget is exhausted)."""
        CEGARLoop._fallback_counter += 1
        name = f"cegar_fallback_{CEGARLoop._fallback_counter}"
        sorts = [v.sort() for v in self.state_vars]
        return verify_transition_system(name, sorts, self.init_cond,
                                        self.trans_rel, self.safety)["safe"]

    def _finish_with_fallback(self, iterations, predicates):
        safe = self._concrete_verdict()
        return CEGARResult(safe, iterations, list(predicates))

    # -- main loop -----------------------------------------------------------

    def run(self):
        """Iterate the CEGAR loop; see class docstring.  Terminates when the
        system is proven safe, a real counterexample is found, or the
        iteration/predicate budget is exceeded."""
        for iteration in range(1, self.max_iterations + 1):
            # 1. Verify with the current abstraction (Spacer over Horn).
            safe, trace = self._verify_abstraction()
            # 2. Safe under the abstraction => concretely safe.
            if safe:
                return CEGARResult(True, iteration,
                                   list(self.domain.predicates))
            # 3-4. Unsafe: concretize and validate the counterexample.
            concrete = self._concretize(trace)
            if concrete is not None:
                verdict = self.validator.validate(concrete, self.init_cond,
                                                  self.trans_rel,
                                                  self.safety)
                # 5. Real counterexample: minimize and return.
                if verdict.is_real:
                    original = self._raw_witness(concrete)
                    if not self.validator.validate(
                            original, self.init_cond, self.trans_rel,
                            self.safety).is_real:
                        original = concrete
                    minimized = self.refiner.minimize_cex(original,
                                                          self.trans_rel)
                    result = CEGARResult(False, iteration,
                                         list(self.domain.predicates),
                                         cex=minimized)
                    result.original_cex = original
                    return result
            # 6. Spurious: refine predicates via interpolation.
            spurious = self._symbolic_cex(trace)
            interpolants = self.refiner.extract_interpolants(
                spurious, self.trans_rel)
            before = {p.sexpr() for p in self.domain.predicates}
            merged = self.refiner.strengthen_invariant(
                self.domain.predicates, interpolants)
            added = [p for p in merged if p.sexpr() not in before]
            if not added or len(merged) > self.predicate_budget:
                return self._finish_with_fallback(iteration, merged)
            self.domain = AbstractDomain(merged)
        return self._finish_with_fallback(self.max_iterations,
                                          self.domain.predicates)

